"""Seam coverage for the single-tap Shift language switch (upstream #394).

PuTTY never delivers key-up, so the toggle used to be lost there. Both delivery
shapes must end with exactly one mode change per tap:

* a key-down-only host: the tap is completed by the following key-down;
* a normal host: the key-up completes it and the following key-down does not
  toggle a second time;
* a Shift held as a modifier (Shift + letter) never toggles.
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402
from cinbase import CHINESE_MODE, ENGLISH_MODE  # noqa: E402

VK_SHIFT = 0x10


class CinbaseShiftToggleTests(CinbaseKeyHarness):

    def shift_down(self, service):
        return self.send(service, VK_SHIFT, VK_SHIFT, printable=False, shift=True)

    def shift_up(self, service):
        event = self.key_event(VK_SHIFT, VK_SHIFT, printable=False, shift=False)
        claimed = service.filterKeyUp(event)
        if claimed:
            service.onKeyUp(event)
        return claimed

    def test_keydown_only_host_still_toggles(self):
        service = self.activate_chesimplex()
        self.assertEqual(service.langMode, CHINESE_MODE)

        self.shift_down(service)  # no key-up follows, PuTTY style
        self.send(service, ord("a"), ord("a"), printable=True)

        self.assertEqual(service.langMode, ENGLISH_MODE)

    def test_normal_host_toggles_exactly_once(self):
        service = self.activate_chesimplex()
        self.assertEqual(service.langMode, CHINESE_MODE)

        self.shift_down(service)
        self.shift_up(service)
        self.assertEqual(service.langMode, ENGLISH_MODE)

        self.send(service, ord("a"), ord("a"), printable=True)
        self.assertEqual(service.langMode, ENGLISH_MODE,
                         "the following key toggled a second time")

        self.shift_down(service)
        self.shift_up(service)
        self.assertEqual(service.langMode, CHINESE_MODE)

    def test_shift_as_a_modifier_does_not_toggle(self):
        service = self.activate_chesimplex()

        self.shift_down(service)
        self.send(service, ord("A"), ord("A"), printable=True, shift=True)

        self.assertEqual(service.langMode, CHINESE_MODE)

    def test_toggle_disabled_switch_leaves_the_mode_alone(self):
        service = self.activate_chesimplex()
        service.cfg.switchLangWithShift = False

        self.shift_down(service)
        self.send(service, ord("a"), ord("a"), printable=True)

        self.assertEqual(service.langMode, CHINESE_MODE)


if __name__ == "__main__":
    unittest.main()
